from collections import Counter

def _runs(vals, bg):
    out=[]; i=0
    while i<len(vals):
        j=i+1
        while j<len(vals) and vals[j]==vals[i]: j+=1
        if vals[i]!=bg and j-i>=2: out.append((i,j,vals[i]))
        i=j
    return out

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    top=_runs(g[0],bg); bottom=_runs(g[-1],bg)
    left=_runs([g[r][0] for r in range(h)],bg)
    right=_runs([g[r][-1] for r in range(h)],bg)
    if top and bottom and top[0][2]==bottom[0][2]:
        a,b=top[0],bottom[0]
        if a[1]-a[0] != b[1]-b[0]: return g
        markers=[(r,c,g[r][c]) for r in range(1,h-1) for c in range(w)
                 if g[r][c]!=bg and (a[0]<=c<a[1] or b[0]<=c<b[1])]
        for r,c,color in markers:
            if a[0]<=c<a[1]:
                mate=b[0]+c-a[0]; g[r][c]=4
                for rr in range(1,r): g[rr][c]=color
                if 0<=mate<w:
                    for rr in range(1,h-1): g[rr][mate]=color
            else:
                mate=a[0]+c-b[0]; g[r][c]=4
                for rr in range(r+1,h-1): g[rr][c]=color
                if 0<=mate<w:
                    for rr in range(1,h-1): g[rr][mate]=color
        return g
    if left and right and left[0][2]==right[0][2]:
        a,b=left[0],right[0]
        if a[1]-a[0] != b[1]-b[0]: return g
        markers=[(r,c,g[r][c]) for r in range(h) for c in range(1,w-1)
                 if g[r][c]!=bg and (a[0]<=r<a[1] or b[0]<=r<b[1])]
        for r,c,color in markers:
            if a[0]<=r<a[1]:
                mate=b[0]+r-a[0]; g[r][c]=4
                for cc in range(1,c): g[r][cc]=color
                if 0<=mate<h:
                    # Draw from the free edge up to the paired right-side bar.
                    for cc in range(0,w-1): g[mate][cc]=color
            else:
                mate=a[0]+r-b[0]; g[r][c]=4
                for cc in range(c+1,w-1): g[r][cc]=color
                if 0<=mate<h:
                    # Paired left-side bar bounds the ray on its inside edge.
                    for cc in range(1,w-1): g[mate][cc]=color
        return g
    return g

